head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil73000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_13", entity: "dlt_depEntityDownDepList", countIds: [], cells: [{ childId: "_cell", fn: function (v, i) { return String(v("depNm")); } }] },
        { genId: "c_foreach_9", entity: "dlt_organizationList", countIds: [], cells: [{ childId: "btn_showDetail", fn: function (v, i) { return String(v("depNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.showDetail('11D0', 'downDep');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil73000.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil73000: 진입 키 poporganization 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_organizationForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil73000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_showDetail_onclick
 * @description btn_showDetail 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_showDetail_onclick = async function(e){
    try {
        await scwin.showDetail('' + dlt_organizationList.getCellData(0, "depCd") + '','organization')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil73000.btn_showDetail_onclick' }); }
};

/**
 * @method
 * @name _cell_onclick
 * @description _cell 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin._cell_onclick = async function(e){
    try {
        await scwin.showDetail('' + dlt_depEntityDownDepList.getCellData(0, "depCd") + '','downDep')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil73000._cell_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_showDetail_xhr
 * @description show Detail xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_showDetail_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_showDetail_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_showDetail_xhr", unresolved: "action:self_submit:tx_showDetail_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showDetail
 * @description show Detail 처리
 * @param {String} _depCd _depCd
 * @param {String} flag flag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showDetail = async function (_depCd, flag) {
    // TODO Stage2(규칙 19): jQuery — DOM 탐색 → 대상 컴포넌트 직접 참조/DataList 루프
    $("#downDepListArea1").children("a").removeClass("on");
    // TODO Stage2(규칙 19): jQuery — DOM 탐색 → 대상 컴포넌트 직접 참조/DataList 루프
    $("#downDepListArea2").children("a").removeClass("on");
    if (flag === "downDep") {
        // TODO Stage2(규칙 19): jQuery — 표시/스타일 → show/hide/setStyle/addClass(컴포넌트 API)
        $("#" + _depCd).addClass("on");
    }
    scwin.form_organizationForm.action = "/digital/popOrganization.do";
    $c.util.getComponent('dma_showDetailXhrReq').set('method', "searchOrganizationDetail");
    $c.util.getComponent('dma_showDetailXhrReq').set('depCd', _depCd);
    $c.util.getComponent('txt_detailContent').setValue(await scwin.tx_showDetail_xhr());
};
